          "excerpt": "P.ĐT tạm tính tại thời điểm cuối năm 2025 - đầu năm 2026, khi quy hoạch chi tiết tỷ lệ 1/500 chưa được phê duyệt, TSDĐ trong khoảng từ 700 - 1,100 tỷ đồng, cụ thể: Kịch bản thấp (Min): 700 tỷ đồng, cơ sở tham chiếu tỷ lệ ĐG đất thặng dư/ ĐGNN của dự án AK (2025)~ 4.x lần. Kịch bản cao (Max): 1,100 tỷ đồng, cơ sở tham chiếu mức giá bán căn hộ của dự án AK khoảng 37.7 triệu đồng/m². Tuy nhiên, theo tiến độ hiện tại, thời điểm dự kiến được giao đất của dự án PKG vào khoảng giữa đến cuối năm 2026, muộn hơn so với thời điểm giả định nêu trên => TSDĐ có khả năng tăng cao hơn mức dự kiến. 2. Ước tính TSDĐ theo bảng giá đất và hệ số điều chỉnh mới áp dụng theo luật mới: Theo QH 1/500 mới, Diện tích đất 27,888m; HSSSĐ: 6.5 Đơn giá đất NN: 15.9tr/m2, hệ số đ.c thị trường 1.67 HSSDĐ: 6.5 => Hệ số điề"
