          "source_file": "batch_232.txt",
          "sender": "",
          "excerpt": "P.ĐT đã so sánh đối chiếu danh sách từ 3 phụ lục trên với danh sách đấu giá năm 2025. Qua đó nhận thấy có 1 số khu đất được chuyển tiếp từ kế hoạch 2025 và có bổ sung thêm những khu đất tiềm năng khác. Căn cứ vào vị trí, sự phát triển đô thị của một số khu vực, sự ưu tiên của Cơ quan NN trong triển khai đấu giá (phụ lục 2), phòng đầu tư đề xuất nghiên cứu các khu đất trong phạm vi thành phố Biên Hòa, Long Thành và Nhơn Trạch, cụ thể: - Khu đất khoảng 13,2 ha tại phường Trấn Biên (Khu nhà máy giấy Tân Mai) - Khu đô thị - thương mại - dịch vụ hỗn hợp (khu vực 1) khoảng 51,65 ha tại phường Trấn Biên (Đấu giá Q1/2026) - Khu đất 610.5 ha (thuộc khu A+B KĐT Long Thành) xã Bình An, Long Thành (Đang lập QH phân khu 1/2000, chưa GPMB) - Khu đất khoảng 329 ha (Khu E khu đô thị Long Thành) tại xã Lon"
