          "excerpt": "P.ĐT gửi anh Mr Mike1 -CEO về Chính sách bán hàng dự án Phượng Hoàng như sau: 1. Về giá vốn và giá thành toàn bộ của sản phẩm căn hộ: Mục tiêu: Ngân sách bán hàng 215 tỷ (chưa VAT) để thu về đơn giá bán trung bình 36.5tr/m2. 2. Giả định: - Mr. David mua 1 căn suất nội bộ và thêm 14 căn (tổng sỉ 15 căn) - Nhân viên công ty mua 49 suất nội bộ =>Tổng số căn áp dụng thanh toán sớm 95%: 64 căn Tổng số căn suất nội bộ: 50 căn Và 15 căn áp dụng mua sỉ (Mr. David) Theo giả định hiện tại, phần ngân sách dành cho chiết khấu vượt dự toán khoảng 2 tỷ, dẫn đến thâm hụt so với kế hoạch. Để duy trì tổng chi phí bán hàng trong giới hạn 215 tỷ đồng, Bộ phận SM cần thực hiện điều chỉnh, cắt giảm hoặc tối ưu các nhóm chi phí khác tương ứng. Message by Unknown User"
