          "excerpt": "Thao L - INVT 9/6/2022 4:52 PM Hiệu quả tài chính: IRR = 14,72% và NPV = 698,475. Độ nhạy dự án: Kết luận: Dự án cơ bản đạt hiệu quả tài chính, K.ĐT đề xuất xúc tiến và đàm phán giá nhận chuyển nhượng để dự án đạt hiệu quả tốt hơn. Ghi chú: - Hiện tại yếu tố pháp lý liên quan đến việc “bán” sản phẩm nghỉ dưỡng vẫn chưa được pháp luật quy định rõ ràng (không đúng với mục tiêu của chủ trương đầu tư là chủ đầu tư phải vận hành). - Về quy hoạch: Ngày 23/06/2022, Thủ tướng Chính phủ có Quyết định số 767/QĐ-TTg phê duyệt Nhiệm vụ Quy hoạch chung thành phố Phú Quốc, tỉnh Kiên Giang đến năm 2040. Trên cơ sở đó, tỉnh đang tiến hành lập đồ án QH chung trình Thủ tướng xem xét, phê phê duyệt, dự kiến công tác này hoàn thành trong năm 2023, các chỉ tiêu QH phê duyệt dự kiến sẽ tăng cao hơn so với hiện"
