      "excerpt": "Phòng đang tính an toàn là xây dựng NOXH cao tầng trong dự án, trường hợp sau này xin đóng tiền sử dụng đất NOXH để không phải xây NOXH và chuyển NOXH này thành đất nền thì hiệu quả dự án sẽ được cải thiện hơn. Dự án đang có một số hạn chế và thông tin cần được làm rõ: Chưa có đường kết nối vào dự án. Chưa hình thành dự án. Có một phần nhỏ trong ranh xen cài chưa mua xong (mài trắng trong ranh đất). Pháp lý và nguồn gốc đất chưa được cung cấp cụ thể. Hiện trạng đang là Đất lúa, cao độ thấp so với nền đường dẫn đến chi phí san lấp có thể cao, và đặc trung tại miền Tây có thể bị đội vốn lên đáng kể do thiếu cát san lấp. Đề xuất Dự án có thể được xem là quỹ đất dự trữ cho tương lai của Công ty CKG, trong bối cảnh quỹ đất nội thành tại Rạch Giá hiện nay gần như đã hết và ngày càng khó tìm các ",
