      "name_hint": "theo các phân kỳ như sau",
      "excerpt": "P.ĐT báo cáo anh Mr Mike1 -CEO, bảng FS Phú Quang cập nhật theo phương án NOTM thay thế NOXH: 1. Các giả định thay đổi trong bài tính: - Giá bán và chi phí được cập nhật: Giá bán tham chiếu theo báo cáo thị trường của P.RnD, chi phí tính tăng lên khoảng 10% để phù hợp với tốc độ trượt giá và tình hình xây dựng hiện tại - Tiền sử dụng đất: Bài tính tiền sử dụng đất cập nhật lại giá thị trường (lên khoảng 50tr/m2) để làm số liệu đầu vào, đồng thời tính toán lại theo quy hoạch mới của P.TKQH. P.ĐT đang giả định thời điểm công ty được giao đất và xác định nghĩa vụ tài chính đợt 2 vào năm 2027. Ngoài ra P.ĐT cũng đã ước tính số tiền đối tác phải đóng cho lần giao đất đợt 1 để lấy số khấu trừ cho tiền sử dụng đất đợt 2. - Quy hoạch: P.ĐT đang tính 2 phương án: PA1: NOXH được chuyển thành khu NOT",
      "part": 4
